-- V32 Academy content + progress + navigation visibility fix
-- Source basis: supplied curriculum file + existing V31 lesson titles/descriptions. Theory is an authored study guide, not a claim of verbatim video transcript.

alter table public.learning_progress add column if not exists notes text not null default '';
alter table public.learning_progress add column if not exists quiz_score numeric(5,2);
alter table public.learning_progress add column if not exists started_at timestamptz;
alter table public.learning_progress add column if not exists completed_at timestamptz;

create table if not exists public.app_navigation_visibility (view_key text primary key, label text not null, visible boolean not null default true, sort_order int not null default 0);
alter table public.app_navigation_visibility enable row level security;
drop policy if exists app_navigation_visibility_read on public.app_navigation_visibility;
create policy app_navigation_visibility_read on public.app_navigation_visibility for select to authenticated using (true);
drop policy if exists app_navigation_visibility_admin on public.app_navigation_visibility;
create policy app_navigation_visibility_admin on public.app_navigation_visibility for all to authenticated using (public.is_admin()) with check (public.is_admin());
insert into public.app_navigation_visibility(view_key,label,visible,sort_order) values
