on conflict(view_key) do nothing;

-- Keep the curriculum exactly at 68 published lessons. Old V29/V30 lesson rows are archived by status rather than hard-deleted.
update public.learning_lessons set content=$${"videoUrl":"","article":"База урока — не отдельный сигнал, а набор принципов, по которым принимается решение. В исходном описании акцент стоит на базовых принципах торговли и на переходе от случайных входов к понятной логике.","examples":"Записанный первый эфир: базовые принципы торговли, сигналы, первые сделки и фундамент дальнейшего обучения.","practice":"Возьми 5 исторических ситуаций и для каждой до открытия сделки запиши: что ты наблюдаешь, какой базовый принцип применяешь и какое условие заставит тебя пропустить вход. Сравни решение с результатом, не меняя исходные правила задним числом.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Первый эфир — базовые принципы торговли». Ситуация: Трейдер видит сигнал, но не может объяснить, почему именно сейчас вход соответствует его плану. Что из перечисленного лучше всего соответствует теме «базовые принципы торговли»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"отложить вход до появления понятного основания","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: решение должно опираться на понятную логику, а не на случайный вход."},{"id":"q2","type":"multi_select","question":"В уроке «Первый эфир — базовые принципы торговли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"отложить вход до появления понятного основания","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"решение должно опираться на понятную логику, а не на случайный вход","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «базовые принципы торговли» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Первый эфир — базовые принципы торговли». Для темы «базовые принципы торговли» можно пропустить проверку ситуации, если уже выполнено условие: отложить вход до появления понятного основания.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «базовые принципы торговли» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Первый эфир — базовые принципы торговли». Какое действие здесь является главным нарушением логики темы «базовые принципы торговли»?","options":[{"value":"A","label":"открыть сделку только потому, что движение уже началось","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно базовые принципы торговли перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: решение должно опираться на понятную логику, а не на случайный вход."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «базовые принципы торговли» в уроке «Первый эфир — базовые принципы торговли»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Первый эфир посвящён базовым принципам торговли и переходу от случайных входов к понятной логике решения.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","facts":["Сначала формулируй причину входа, а уже потом нажимай кнопку сделки.","Сигнал без объяснимого принципа не превращается в устойчивую систему.","Базовые правила должны быть одинаковыми от сделки к сделке."],"sourceTitle":"Первый эфир — базовые принципы торговли","sourceDuration":"50 минут 7 секунд","lessonFormat":"video","sourceOrder":1,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='basics-first-live';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Японская свеча показывает не только направление движения, но и борьбу покупателей и продавцов за выбранный период. Важна форма свечи и её место на графике: одна свеча сама по себе не должна становиться автоматическим сигналом.","examples":"Третий эфир: японские свечи, чтение свечей, настроение рынка, логика входа и домашнее задание.","practice":"На истории выбери 10 свечей в разных контекстах. Для каждой опиши тело, тени, направление предыдущего движения и настроение, которое она может отражать. Затем отдельно отметь 3 случая, где одна свеча сама по себе не даёт основания для входа.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Свечи, которые дают деньги». Ситуация: После сильного движения появилась свеча с маленьким телом и длинной тенью. Что из перечисленного лучше всего соответствует теме «японские свечи»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сопоставить свечу с предшествующим движением и дождаться развития реакции","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей."},{"id":"q2","type":"multi_select","question":"В уроке «Свечи, которые дают деньги» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сопоставить свечу с предшествующим движением и дождаться развития реакции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «японские свечи» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Свечи, которые дают деньги». Для темы «японские свечи» можно пропустить проверку ситуации, если уже выполнено условие: сопоставить свечу с предшествующим движением и дождаться развития реакции.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «японские свечи» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Свечи, которые дают деньги». Какое действие здесь является главным нарушением логики темы «японские свечи»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно японские свечи перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать одну необычную свечу самостоятельным сигналом","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: форма тела и теней имеет смысл вместе с предыдущим движением и реакцией следующих свечей."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «японские свечи» в уроке «Свечи, которые дают деньги»?","options":[{"value":"A","label":"Урок посвящён японским свечам, чтению их формы, настроению рынка и логике входа.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Смотри на свечу в контексте предыдущего движения.","facts":["Смотри на свечу в контексте предыдущего движения.","Форма свечи помогает оценить настроение рынка, но не заменяет подтверждение.","Логику входа нужно объяснять до открытия сделки."],"sourceTitle":"Свечи, которые дают деньги","sourceDuration":"42 минуты 37 секунд","lessonFormat":"video","sourceOrder":2,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='candles-third-live';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Горизонтальный уровень — это область цены, где рынок уже реагировал. Задача анализа не в том, чтобы провести красивую линию, а в том, чтобы найти повторяющуюся реакцию и проверить её контекстом.","examples":"Второй эфир: что такое горизонтальные уровни, как их находить и использовать; в эфире разобраны три сделки.","practice":"Найди 5 горизонтальных уровней и подготовь по каждому сценарий входа. Для каждого укажи, что должно произойти возле уровня, чтобы вход стал оправданным, и что заставит тебя отказаться от сделки.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Горизонтальные уровни». Ситуация: На одном ценовом участке рынок уже несколько раз реагировал, но текущий подход к нему очень быстрый. Что из перечисленного лучше всего соответствует теме «горизонтальные уровни»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценить реакцию цены в области и контекст подхода","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии."},{"id":"q2","type":"multi_select","question":"В уроке «Горизонтальные уровни» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценить реакцию цены в области и контекст подхода","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «горизонтальные уровни» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Горизонтальные уровни». Если выполнить условие «оценить реакцию цены в области и контекст подхода», тема «горизонтальные уровни» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «горизонтальные уровни» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Горизонтальные уровни». Какое действие здесь является главным нарушением логики темы «горизонтальные уровни»?","options":[{"value":"A","label":"входить только потому, что цена снова коснулась отметки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно горизонтальные уровни перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: уровень ценен повторяющейся реакцией рынка, а не точностью нарисованной линии."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «горизонтальные уровни» в уроке «Горизонтальные уровни»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Горизонтальный уровень в уроке рассматривается как область повторной реакции цены, а не как идеально точная линия.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Ищи повторные реакции цены, а не одиночное касание.","facts":["Ищи повторные реакции цены, а не одиночное касание.","Уровень должен иметь смысл в структуре движения.","Перед входом оцени, как цена подошла к уровню и что делает после реакции."],"sourceTitle":"Горизонтальные уровни","sourceDuration":"43 минуты 36 секунд","lessonFormat":"video","sourceOrder":3,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='technical-horizontal-levels';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Поддержка и сопротивление лучше воспринимать как зоны, а не как математически точные линии. Цена может проколоть край зоны и всё равно сохранить её смысл. Само касание уровня не является достаточной причиной для входа.","examples":"Короткий материал о поддержке и сопротивлении: уровни нужно воспринимать как зоны и не входить только потому, что цена коснулась зоны.","practice":"Возьми 5 участков графика и вместо линий отметь зоны. Для каждой зоны запиши границы, реакцию цены внутри неё и место, где твой первоначальный сценарий перестаёт быть актуальным.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Уровни — это зоны, а не линии». Ситуация: Цена немного проколола край зоны, после чего появилась реакция внутри той же области. Что из перечисленного лучше всего соответствует теме «уровни как зоны»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"продолжить оценивать зону по реакции и сценарию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону."},{"id":"q2","type":"multi_select","question":"В уроке «Уровни — это зоны, а не линии» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"продолжить оценивать зону по реакции и сценарию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «уровни как зоны» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Уровни — это зоны, а не линии». Для темы «уровни как зоны» можно пропустить проверку ситуации, если уже выполнено условие: продолжить оценивать зону по реакции и сценарию.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «уровни как зоны» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Уровни — это зоны, а не линии». Какое действие здесь является главным нарушением логики темы «уровни как зоны»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно уровни как зоны перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать зону недействительной из-за любого прокола","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: поддержка и сопротивление имеют ширину, а прокол края не обязательно отменяет зону."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «уровни как зоны» в уроке «Уровни — это зоны, а не линии»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Поддержку и сопротивление в уроке предлагается воспринимать как зоны, а не как математически точные линии.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Зона имеет ширину и допускает шум цены.","facts":["Зона имеет ширину и допускает шум цены.","Касание зоны ≠ готовый сигнал.","Нужен контекст и подтверждение реакции цены."],"sourceTitle":"Уровни — это зоны, а не линии","sourceDuration":"1 минута 31 секунда","lessonFormat":"video","sourceOrder":4,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='technical-levels-zones';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Order Block» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный инструмент технического анализа: Order Block.","practice":"Найди 3 участка, где ты считаешь, что присутствует Order Block. Для каждого объясни, какое движение до и после него заставляет тебя выделить эту область и какое подтверждение ты ждёшь перед решением.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Order Block». Ситуация: После участка цены началось сильное движение, и трейдер хочет сразу назвать исходную область Order Block. Что из перечисленного лучше всего соответствует теме «Order Block»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала разобрать движение до и после области и условие подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"использовать область без проверки контекста","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования."},{"id":"q2","type":"multi_select","question":"В уроке «Order Block» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"использовать область без проверки контекста","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала разобрать движение до и после области и условие подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «Order Block» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Order Block». Если выполнить условие «сначала разобрать движение до и после области и условие подтверждения», тема «Order Block» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Order Block» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Order Block». Какое действие здесь является главным нарушением логики темы «Order Block»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"использовать область без проверки контекста","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно Order Block перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: область нельзя называть Order Block только по одному факту последующего движения; нужен контекст формирования."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Order Block» в уроке «Order Block»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В уроке Order Block решение разбирается последовательно: что наблюдаем, что это означает, какое условие должно появиться и когда лучше пропустить.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Основная тема материала — Order Block.","facts":["Основная тема материала — Order Block.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Block","sourceDuration":"10 минут 28 секунд","lessonFormat":"video","sourceOrder":5,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-order-block';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Order Flow» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Отдельный материал по Order Flow и чтению потока сделок.","practice":"На трёх исторических участках попробуй описать Order Flow словами: кто проявляет инициативу, где давление меняется и что происходит с ценой после этого. Не используй название индикатора как объяснение — опиши наблюдаемое поведение.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Order Flow». Ситуация: Цена почти не растёт, хотя давление покупателей заметно усиливается. Что из перечисленного лучше всего соответствует теме «Order Flow»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сравнить изменение давления с реакцией цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены."},{"id":"q2","type":"multi_select","question":"В уроке «Order Flow» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сравнить изменение давления с реакцией цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «Order Flow» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Order Flow». Для темы «Order Flow» можно пропустить проверку ситуации, если уже выполнено условие: сравнить изменение давления с реакцией цены.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Order Flow» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Order Flow». Какое действие здесь является главным нарушением логики темы «Order Flow»?","options":[{"value":"A","label":"игнорировать цену и считать давление гарантией продолжения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Order Flow перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: важно наблюдать изменение давления покупателей и продавцов и сопоставлять его с движением цены."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Order Flow» в уроке «Order Flow»?","options":[{"value":"A","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В уроке Order Flow важен анализ изменения давления покупателей и продавцов вместе с движением цены.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Основная тема материала — Order Flow.","facts":["Основная тема материала — Order Flow.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Order Flow","sourceDuration":"9 минут 49 секунд","lessonFormat":"video","sourceOrder":6,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-order-flow';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Fair Value Gap» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал по Fair Value Gap как отдельному инструменту чтения движения цены.","practice":"Найди 5 возможных Fair Value Gap. Для каждого отметь контекст появления, направление импульса и что произошло с ценой после формирования области. Два спорных примера специально пометь как спорные.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Fair Value Gap». Ситуация: После импульса цена возвращается к области, которую трейдер отметил как FVG. Что из перечисленного лучше всего соответствует теме «Fair Value Gap»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценить формирование области и реакцию цены при возврате","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"входить автоматически при первом касании области","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении."},{"id":"q2","type":"multi_select","question":"В уроке «Fair Value Gap» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить автоматически при первом касании области","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"оценить формирование области и реакцию цены при возврате","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Fair Value Gap» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Fair Value Gap». Для темы «Fair Value Gap» можно пропустить проверку ситуации, если уже выполнено условие: оценить формирование области и реакцию цены при возврате.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Fair Value Gap» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Fair Value Gap». Какое действие здесь является главным нарушением логики темы «Fair Value Gap»?","options":[{"value":"A","label":"проверить именно Fair Value Gap перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить автоматически при первом касании области","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важно анализировать область дисбаланса по тому, как она сформировалась и как цена ведёт себя при возвращении."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Fair Value Gap» в уроке «Fair Value Gap»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В уроке Fair Value Gap область нужно оценивать через её формирование и реакцию цены при возвращении.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Основная тема материала — Fair Value Gap.","facts":["Основная тема материала — Fair Value Gap.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Fair Value Gap","sourceDuration":"13 минут 18 секунд","lessonFormat":"video","sourceOrder":7,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='tools-fair-value-gap';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Индикатор — это инструмент чтения уже сформированного движения, а не самостоятельная кнопка BUY/SELL. В уроке собраны MACD, Stochastic, Awesome Oscillator, RSI и Momentum; смысл изучения — понимать, какую информацию даёт каждый инструмент и не перегружать решение.","examples":"Четвёртый эфир: MACD, Stochastic, Awesome Oscillator, RSI и Momentum.","practice":"Для каждого из MACD, Stochastic, Awesome Oscillator, RSI и Momentum найди по одному историческому примеру. Запиши, какую информацию ты получал от индикатора и какое решение принял бы только после проверки контекста.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Индикаторы для уверенной торговли». Ситуация: RSI показывает интересную зону, но структура цены не подтверждает сценарий. Что из перечисленного лучше всего соответствует теме «индикаторы для уверенной торговли»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"использовать показание индикатора как часть решения, а не как кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить только по показанию RSI","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: MACD, Stochastic, Awesome Oscillator, RSI и Momentum дают разные типы информации и не заменяют контекст."},{"id":"q2","type":"multi_select","question":"В уроке «Индикаторы для уверенной торговли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"MACD, Stochastic, Awesome Oscillator, RSI и Momentum дают разные типы информации и не заменяют контекст","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать показание индикатора как часть решения, а не как кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"входить только по показанию RSI","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «индикаторы для уверенной торговли» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Индикаторы для уверенной торговли». Если выполнить условие «использовать показание индикатора как часть решения, а не как кнопку входа», тема «индикаторы для уверенной торговли» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «индикаторы для уверенной торговли» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Индикаторы для уверенной торговли». Какое действие здесь является главным нарушением логики темы «индикаторы для уверенной торговли»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"входить только по показанию RSI","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно индикаторы для уверенной торговли перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: MACD, Stochastic, Awesome Oscillator, RSI и Momentum дают разные типы информации и не заменяют контекст."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «индикаторы для уверенной торговли» в уроке «Индикаторы для уверенной торговли»?","options":[{"value":"A","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В четвёртом эфире рассматриваются MACD, Stochastic, Awesome Oscillator, RSI и Momentum как разные источники информации.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Не смешивай несколько индикаторов без понятной роли каждого.","facts":["Не смешивай несколько индикаторов без понятной роли каждого.","Сигнал индикатора нужно сопоставлять с графиком и контекстом.","Настройки и таймфрейм меняют характер сигнала."],"sourceTitle":"Индикаторы для уверенной торговли","sourceDuration":"49 минут 37 секунд","lessonFormat":"video","sourceOrder":8,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-fourth-live';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"DeMarker используется для оценки состояния движения через положение относительно зон 80/20. В исходном материале указаны период 10, таймфрейм 15 секунд и экспирация M3, а также наблюдение за пересечением уровней на нескольких свечах.","examples":"DeMarker: период 10, уровни 80/20, гистограмма, таймфрейм 15 секунд и экспирация M3; в описании указано ждать пересечение 3–5 свечей.","practice":"Настрой DeMarker по параметрам урока и проведи 10 наблюдений на M15-ситуациях. Для каждого отметь состояние индикатора, направление рынка и был ли сигнал достаточно устойчивым для решения.","quiz":[{"id":"q1","type":"single_select","question":"Урок «DeMarker». Ситуация: DeMarker вышел в область 80, но направление рынка остаётся устойчивым и подтверждения разворота нет. Что из перечисленного лучше всего соответствует теме «DeMarker»?","options":[{"value":"A","label":"учесть положение индикатора вместе с направлением рынка и развитием сигнала","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать уровень 80 автоматическим разворотом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: в уроке используются период 10, уровни 80/20, 15-секундный график и M3; сигнал оценивается не по одному касанию."},{"id":"q2","type":"multi_select","question":"В уроке «DeMarker» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"в уроке используются период 10, уровни 80/20, 15-секундный график и M3; сигнал оценивается не по одному касанию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать уровень 80 автоматическим разворотом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"учесть положение индикатора вместе с направлением рынка и развитием сигнала","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «DeMarker» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «DeMarker». Если выполнить условие «учесть положение индикатора вместе с направлением рынка и развитием сигнала», тема «DeMarker» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «DeMarker» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «DeMarker». Какое действие здесь является главным нарушением логики темы «DeMarker»?","options":[{"value":"A","label":"проверить именно DeMarker перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"считать уровень 80 автоматическим разворотом","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: в уроке используются период 10, уровни 80/20, 15-секундный график и M3; сигнал оценивается не по одному касанию."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «DeMarker» в уроке «DeMarker»?","options":[{"value":"A","label":"В исходном материале DeMarker задан периодом 10 и уровнями 80/20.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Период: 10; ориентиры: 80/20.","facts":["Период: 10; ориентиры: 80/20.","Не реагируй на единичное касание — смотри на развитие сигнала.","Контекст тренда и волатильности остаётся важен даже при наличии индикатора."],"sourceTitle":"DeMarker","sourceDuration":"5 минут 7 секунд","lessonFormat":"video","sourceOrder":9,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-demarker';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"В уроке Moving Average рассматривается через периоды 2 и 5, таймфрейм 30 секунд и экспирацию M2. Ключевая идея — наблюдать пересечение средних как изменение краткосрочного баланса, а не считать само пересечение гарантией сделки.","examples":"Moving Average: периоды 2 и 5, таймфрейм 30 секунд, экспирация M2 и логика пересечения.","practice":"Настрой две Moving Average с периодами из урока. Найди 5 пересечений и раздели их на ситуации, где движение продолжилось, и ситуации, где пересечение оказалось слабым. Объясни различие контекстом.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Moving Average». Ситуация: MA 2 и MA 5 пересеклись, после чего цена сразу вернулась назад. Что из перечисленного лучше всего соответствует теме «Moving Average»?","options":[{"value":"A","label":"считать любое пересечение гарантированным входом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценить качество пересечения по дальнейшему движению","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: в уроке используются периоды 2 и 5, 30 секунд и M2; пересечение показывает изменение краткосрочной динамики, но не гарантирует сделку."},{"id":"q2","type":"multi_select","question":"В уроке «Moving Average» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать любое пересечение гарантированным входом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"в уроке используются периоды 2 и 5, 30 секунд и M2; пересечение показывает изменение краткосрочной динамики, но не гарантирует сделку","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"оценить качество пересечения по дальнейшему движению","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Moving Average» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Moving Average». Для темы «Moving Average» можно пропустить проверку ситуации, если уже выполнено условие: оценить качество пересечения по дальнейшему движению.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Moving Average» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Moving Average». Какое действие здесь является главным нарушением логики темы «Moving Average»?","options":[{"value":"A","label":"проверить именно Moving Average перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"считать любое пересечение гарантированным входом","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: в уроке используются периоды 2 и 5, 30 секунд и M2; пересечение показывает изменение краткосрочной динамики, но не гарантирует сделку."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Moving Average» в уроке «Moving Average»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В исходном материале Moving Average использует периоды 2 и 5, 30-секундный график и M2.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Периоды 2 и 5 задают очень быстрые средние.","facts":["Периоды 2 и 5 задают очень быстрые средние.","Пересечение показывает изменение краткосрочной динамики.","Закрытие свечи важно: не принимай решение по незавершённой свече."],"sourceTitle":"Moving Average","sourceDuration":"3 минуты 2 секунды","lessonFormat":"video","sourceOrder":10,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-moving-average';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Stochastic в исходном материале задан уровнями 20/80 и параметрами K14, D3, slowing3. Урок отдельно подчёркивает работу после закрытия свечи и учёт тренда.","examples":"Stochastic: уровни 20/80, K14, D3, slowing 3, M5/M1, работа после закрытия свечи и учёт тренда.","practice":"Настрой Stochastic по параметрам урока. Найди 6 сигналов в разных условиях и для каждого дождись закрытия свечи. Отдельно отметь, как направление тренда изменило бы твоё решение.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Stochastic». Ситуация: Stochastic дал сигнал на незакрытой свече внутри сильного тренда. Что из перечисленного лучше всего соответствует теме «Stochastic»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"дождаться закрытия свечи и оценить сигнал относительно тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда."},{"id":"q2","type":"multi_select","question":"В уроке «Stochastic» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"дождаться закрытия свечи и оценить сигнал относительно тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Stochastic» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Stochastic». Если выполнить условие «дождаться закрытия свечи и оценить сигнал относительно тренда», тема «Stochastic» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Stochastic» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Stochastic». Какое действие здесь является главным нарушением логики темы «Stochastic»?","options":[{"value":"A","label":"проверить именно Stochastic перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"входить до закрытия свечи только из-за положения Stochastic","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: параметры K14/D3/slowing3, уровни 20/80; решение принимается после закрытия свечи и с учётом тренда."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Stochastic» в уроке «Stochastic»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"В исходном материале Stochastic задан K14, D3, slowing3 и уровнями 20/80.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"20/80 — зоны, а не автоматические точки входа.","facts":["20/80 — зоны, а не автоматические точки входа.","Параметры K14/D3/slowing3 должны оставаться фиксированными при отработке учебного сценария.","Сигнал оценивается вместе с трендом и закрытием свечи."],"sourceTitle":"Stochastic","sourceDuration":"7 минут 28 секунд","lessonFormat":"video","sourceOrder":11,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='indicators-stochastic';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Пробой — это не просто выход цены за линию. В уроке акцент сделан на поиске пробоя, отличии настоящего движения от фейк-пробоя и выборе точки входа. Поэтому сначала определяется уровень и контекст, затем оценивается реакция после выхода.","examples":"Как торговать пробои, находить их, избегать главных ошибок, видеть фейк-пробои и выбирать точки входа.","practice":"Найди 5 пробоев: два качественных, два ложных и один спорный. Для каждого до просмотра результата сформулируй сценарий, точку входа и условие отмены. Только после этого проверь, что произошло.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Стратегия торговли по пробоям». Ситуация: Цена вышла выше уровня, но почти сразу вернулась обратно под него. Что из перечисленного лучше всего соответствует теме «торговля по пробоям»?","options":[{"value":"A","label":"рассмотреть сценарий фейк-пробоя и дождаться подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать любой выход за уровень настоящим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: пробой оценивается вместе с уровнем, контекстом и поведением цены после выхода."},{"id":"q2","type":"multi_select","question":"В уроке «Стратегия торговли по пробоям» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"рассмотреть сценарий фейк-пробоя и дождаться подтверждения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать любой выход за уровень настоящим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"пробой оценивается вместе с уровнем, контекстом и поведением цены после выхода","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «торговля по пробоям» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Стратегия торговли по пробоям». Если выполнить условие «рассмотреть сценарий фейк-пробоя и дождаться подтверждения», тема «торговля по пробоям» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «торговля по пробоям» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Стратегия торговли по пробоям». Какое действие здесь является главным нарушением логики темы «торговля по пробоям»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать любой выход за уровень настоящим пробоем","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно торговля по пробоям перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: пробой оценивается вместе с уровнем, контекстом и поведением цены после выхода."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «торговля по пробоям» в уроке «Стратегия торговли по пробоям»?","options":[{"value":"A","label":"В стратегии пробоев отдельно нужно отличать настоящий выход за уровень от фейк-пробоя и учитывать реакцию после выхода.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Пробой нужно отличать от ложного выхода за уровень.","facts":["Пробой нужно отличать от ложного выхода за уровень.","Контекст и качество движения важнее самого факта пересечения.","Точка входа должна иметь объяснимую причину, а не строиться на погоне за движением."],"sourceTitle":"Стратегия торговли по пробоям","sourceDuration":"14 минут 3 секунды","lessonFormat":"video","sourceOrder":12,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-breakouts';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Связка SuperTrend + Moving Average нужна для согласования направления движения. SuperTrend даёт контекст направления, а средняя помогает видеть краткосрочную динамику. Примеры в источнике показывают применение на коротком таймфрейме.","examples":"Связка SuperTrend + Moving Average на коротком таймфрейме; в примерах указаны AUD/CAD и EUR/GBP, 1 минута и сделки по +$89.","practice":"На истории найди 5 пересечений/совпадений SuperTrend и Moving Average. Для каждого запиши направление, контекст и решение: входить, ждать или пропустить. Обязательно объясни выбор.","quiz":[{"id":"q1","type":"single_select","question":"Урок «SuperTrend + Moving Average». Ситуация: SuperTrend и MA указывают вверх, но цена находится в слабой структуре без продолжения. Что из перечисленного лучше всего соответствует теме «SuperTrend + Moving Average»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить, подтверждается ли согласованный сигнал поведением цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании."},{"id":"q2","type":"multi_select","question":"В уроке «SuperTrend + Moving Average» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"проверить, подтверждается ли согласованный сигнал поведением цены","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «SuperTrend + Moving Average» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «SuperTrend + Moving Average». Для темы «SuperTrend + Moving Average» можно пропустить проверку ситуации, если уже выполнено условие: проверить, подтверждается ли согласованный сигнал поведением цены.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «SuperTrend + Moving Average» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «SuperTrend + Moving Average». Какое действие здесь является главным нарушением логики темы «SuperTrend + Moving Average»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно SuperTrend + Moving Average перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку только из-за совпадения двух индикаторов","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: SuperTrend помогает оценивать направление, MA — краткосрочную динамику; решение строится на согласовании."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «SuperTrend + Moving Average» в уроке «SuperTrend + Moving Average»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Связка SuperTrend + Moving Average использует SuperTrend для направления, а Moving Average для краткосрочной динамики.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","facts":["Оба инструмента должны выполнять разные роли, а не дублировать друг друга.","Сначала определяй направление, затем ищи точку входа.","Примеры сделок не превращают сигнал в гарантию результата."],"sourceTitle":"SuperTrend + Moving Average","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":13,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-supertrend-ma';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Donchian Channel с периодом 22 показывает диапазон экстремумов выбранного числа свечей. В исходном сценарии используется M1 и экспирация 1–2 минуты. Смысл инструмента — видеть границы текущего диапазона и оценивать выход из него.","examples":"Donchian Channel: период 22, M1, экспирация 1–2 минуты.","practice":"Настрой Donchian Channel с периодом 22. Найди 5 выходов цены за границы и проверь, что произошло в следующие 1–2 минуты. Раздели случаи по качеству и объясни причины.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Donchian Channel». Ситуация: На M1 цена подходит к верхней границе Donchian после длительного движения внутри диапазона. Что из перечисленного лучше всего соответствует теме «Donchian Channel»?","options":[{"value":"A","label":"оценить, происходит ли реальный выход из диапазона","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты."},{"id":"q2","type":"multi_select","question":"В уроке «Donchian Channel» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценить, происходит ли реальный выход из диапазона","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «Donchian Channel» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Donchian Channel». Если выполнить условие «оценить, происходит ли реальный выход из диапазона», тема «Donchian Channel» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Donchian Channel» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Donchian Channel». Какое действие здесь является главным нарушением логики темы «Donchian Channel»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно Donchian Channel перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать касание верхней границы автоматическим пробоем","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: период 22 показывает диапазон экстремумов выбранных свечей; сценарий урока — M1 и экспирация 1–2 минуты."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Donchian Channel» в уроке «Donchian Channel»?","options":[{"value":"A","label":"В исходном материале Donchian использует период 22, M1 и экспирацию 1–2 минуты.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Период 22 задаёт окно наблюдения.","facts":["Период 22 задаёт окно наблюдения.","Граница канала отражает недавний максимум/минимум, а не будущее направление.","Выход за границу нужно оценивать вместе с контекстом."],"sourceTitle":"Donchian Channel","sourceDuration":"4 минуты 17 секунд","lessonFormat":"video","sourceOrder":14,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-donchian';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Стратегия Александра объединяет Bollinger Bands, RSI и Moving Average. В источнике указаны Bollinger period 20, deviation 2 и EMA, а рабочий контекст — M2–M3. Сила схемы в совместном чтении цены, волатильности и импульса.","examples":"Bollinger Bands + RSI + Moving Average; Bollinger period 20, deviation 2, EMA, M2–M3.","practice":"Собери 5 исторических ситуаций по связке Bollinger Bands + RSI + Moving Average. Не ищи совпадение всех трёх индикаторов механически: опиши, что каждый из них добавляет к решению и где сценарий лучше пропустить.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Стратегия Александра». Ситуация: Bollinger и RSI дают разные намёки, а EMA не подтверждает направление. Что из перечисленного лучше всего соответствует теме «стратегия Александра»?","options":[{"value":"A","label":"не считать набор разрозненных сигналов согласованной схемой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"входить потому, что хотя бы один индикатор дал сигнал","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: связка использует Bollinger 20/2, RSI и EMA; смысл — совместно читать цену, волатильность и импульс."},{"id":"q2","type":"multi_select","question":"В уроке «Стратегия Александра» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"входить потому, что хотя бы один индикатор дал сигнал","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"не считать набор разрозненных сигналов согласованной схемой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"связка использует Bollinger 20/2, RSI и EMA; смысл — совместно читать цену, волатильность и импульс","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «стратегия Александра» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Стратегия Александра». Если выполнить условие «не считать набор разрозненных сигналов согласованной схемой», тема «стратегия Александра» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «стратегия Александра» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Стратегия Александра». Какое действие здесь является главным нарушением логики темы «стратегия Александра»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"входить потому, что хотя бы один индикатор дал сигнал","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно стратегия Александра перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: связка использует Bollinger 20/2, RSI и EMA; смысл — совместно читать цену, волатильность и импульс."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «стратегия Александра» в уроке «Стратегия Александра»?","options":[{"value":"A","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В исходном материале стратегии Александра указаны Bollinger 20, deviation 2, RSI и EMA.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Bollinger показывает положение цены внутри динамического диапазона.","facts":["Bollinger показывает положение цены внутри динамического диапазона.","RSI добавляет информацию о силе движения.","Moving Average помогает не потерять направление контекста."],"sourceTitle":"Стратегия Александра","sourceDuration":"4 минуты 9 секунд","lessonFormat":"video","sourceOrder":15,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-alexander';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Связка Schaff Trend Cycle + Donchian Channel сочетает оценку трендового импульса с границами диапазона. Один инструмент отвечает за состояние движения, другой — за положение цены относительно экстремумов.","examples":"Связка Schaff Trend Cycle и Donchian Channel для торгового сценария.","practice":"Найди 5 ситуаций, где Schaff Trend Cycle и Donchian Channel дают возможность сформировать единый сценарий. Для каждой запиши, что показывает каждый инструмент и что должно произойти для входа.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Schaff Trend Cycle + Donchian Channel». Ситуация: Schaff показывает изменение импульса, а цена одновременно находится у границы Donchian. Что из перечисленного лучше всего соответствует теме «Schaff Trend Cycle + Donchian Channel»?","options":[{"value":"A","label":"сопоставить состояние импульса с положением цены в диапазоне","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"рассматривать оба индикатора как два одинаковых сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: Schaff оценивает состояние трендового импульса, Donchian — положение относительно экстремумов диапазона."},{"id":"q2","type":"multi_select","question":"В уроке «Schaff Trend Cycle + Donchian Channel» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"рассматривать оба индикатора как два одинаковых сигнала","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Schaff оценивает состояние трендового импульса, Donchian — положение относительно экстремумов диапазона","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сопоставить состояние импульса с положением цены в диапазоне","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Schaff Trend Cycle + Donchian Channel» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Schaff Trend Cycle + Donchian Channel». Если выполнить условие «сопоставить состояние импульса с положением цены в диапазоне», тема «Schaff Trend Cycle + Donchian Channel» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Schaff Trend Cycle + Donchian Channel» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Schaff Trend Cycle + Donchian Channel». Какое действие здесь является главным нарушением логики темы «Schaff Trend Cycle + Donchian Channel»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно Schaff Trend Cycle + Donchian Channel перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"рассматривать оба индикатора как два одинаковых сигнала","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: Schaff оценивает состояние трендового импульса, Donchian — положение относительно экстремумов диапазона."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Schaff Trend Cycle + Donchian Channel» в уроке «Schaff Trend Cycle + Donchian Channel»?","options":[{"value":"A","label":"Schaff Trend Cycle и Donchian Channel выполняют разные роли: состояние трендового импульса и положение цены относительно экстремумов.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","facts":["Не рассматривай два индикатора как два независимых сигнала BUY/SELL.","Ищи согласование направления и положения цены.","Если контекст противоречивый, решение должно быть пропущено, а не выдумано."],"sourceTitle":"Schaff Trend Cycle + Donchian Channel","sourceDuration":"6 минут 33 секунды","lessonFormat":"video","sourceOrder":16,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-schaff-donchian';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Moving Average помогает читать направление/динамику, а Fractals — локальные экстремумы. Их совместное использование полезно, когда экстремум оценивается относительно текущего направления, а не сам по себе.","examples":"Торговый сценарий с Moving Average и Fractals.","practice":"Найди 5 примеров взаимодействия Moving Average и Fractals. Для каждого опиши направление, локальный экстремум и момент, когда решение становится достаточно определённым.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Moving Average + Fractals». Ситуация: Fractal появился против текущего направления, которое уверенно показывает MA. Что из перечисленного лучше всего соответствует теме «Moving Average + Fractals»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценить fractal внутри контекста направления MA","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики."},{"id":"q2","type":"multi_select","question":"В уроке «Moving Average + Fractals» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценить fractal внутри контекста направления MA","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «Moving Average + Fractals» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Moving Average + Fractals». Для темы «Moving Average + Fractals» можно пропустить проверку ситуации, если уже выполнено условие: оценить fractal внутри контекста направления MA.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Moving Average + Fractals» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Moving Average + Fractals». Какое действие здесь является главным нарушением логики темы «Moving Average + Fractals»?","options":[{"value":"A","label":"использовать любой fractal как самостоятельный разворот","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Moving Average + Fractals перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: MA даёт контекст направления, Fractals — локальные экстремумы; экстремум нужно оценивать относительно динамики."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Moving Average + Fractals» в уроке «Moving Average + Fractals»?","options":[{"value":"A","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Moving Average задаёт контекст направления, а Fractals показывают локальные экстремумы, которые нужно оценивать внутри этого контекста.","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Фрактал — это локальная структура, а не самостоятельная причина входа.","facts":["Фрактал — это локальная структура, а не самостоятельная причина входа.","MA задаёт контекст направления.","Сначала оцени структуру, затем ищи точку решения."],"sourceTitle":"Moving Average + Fractals","sourceDuration":"5 минут 21 секунда","lessonFormat":"video","sourceOrder":17,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-ma-fractals';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Сценарий Giant Candle из источника относится к OTC: таймфрейм 5 секунд, большая свеча сравнивается с 3–5 предыдущими, после чего рассматривается противоположный вход с экспирацией 3 секунды. Это специальный сценарий, который нельзя переносить на любой график без проверки условий.","examples":"OTC, таймфрейм 5 секунд, большая свеча против 3–5 предыдущих, вход в противоположную сторону, экспирация 3 секунды; только после новой ситуации.","practice":"Найди 5 примеров Giant Candle и сначала опиши ситуацию без просмотра следующих свечей. Отметь, соответствует ли движение условиям урока и что должно произойти, чтобы сценарий был отменён.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Giant Candle». Ситуация: На обычной валютной паре появляется большая свеча, но условия OTC-сценария урока не выполнены. Что из перечисленного лучше всего соответствует теме «Giant Candle»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"не переносить Giant Candle автоматически на другой рынок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"открыть противоположную сделку только из-за размера свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: сценарий OTC: 5 секунд; большая свеча сравнивается с 3–5 предыдущими; противоположный вход и экспирация 3 секунды."},{"id":"q2","type":"multi_select","question":"В уроке «Giant Candle» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"открыть противоположную сделку только из-за размера свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сценарий OTC: 5 секунд; большая свеча сравнивается с 3–5 предыдущими; противоположный вход и экспирация 3 секунды","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"не переносить Giant Candle автоматически на другой рынок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Giant Candle» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Giant Candle». Для темы «Giant Candle» можно пропустить проверку ситуации, если уже выполнено условие: не переносить Giant Candle автоматически на другой рынок.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Giant Candle» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Giant Candle». Какое действие здесь является главным нарушением логики темы «Giant Candle»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"открыть противоположную сделку только из-за размера свечи","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно Giant Candle перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: сценарий OTC: 5 секунд; большая свеча сравнивается с 3–5 предыдущими; противоположный вход и экспирация 3 секунды."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «Giant Candle» в уроке «Giant Candle»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"В исходном сценарии Giant Candle указаны OTC, 5 секунд, сравнение с 3–5 свечами и экспирация 3 секунды.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","facts":["Сначала должна быть действительно аномально большая свеча относительно 3–5 предыдущих.","Сценарий предусматривает противоположное направление, но только при выполнении условий.","После новой ситуации нельзя механически повторять старый сигнал."],"sourceTitle":"Giant Candle","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":18,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-giant-candle';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Паттерн 2-of-3 строится на последовательности зелёная–красная–зелёная. В источнике указано: обычные валютные пары, 30 секунд, третья зелёная должна закрыться на уровне/выше максимума первой зелёной, экспирация 2 минуты.","examples":"Обычные валютные пары, 30 секунд, последовательность зелёная–красная–зелёная; третья зелёная закрывается на/выше максимума первой; экспирация 2 минуты.","practice":"Найди 5 формаций green-red-green. Для каждой проверь условие по третьей свече только после её полного закрытия. Запиши, соответствует ли структура критериям урока и почему.","quiz":[{"id":"q1","type":"single_select","question":"Урок «2-of-3». Ситуация: Есть зелёная–красная–зелёная, но третья свеча ещё не закрылась и её максимум ниже первой зелёной. Что из перечисленного лучше всего соответствует теме «2-of-3»?","options":[{"value":"A","label":"считать паттерн готовым до закрытия третьей свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ждать полного закрытия третьей свечи и проверки условия максимума","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: последовательность зелёная–красная–зелёная; третья зелёная закрывается на уровне/выше максимума первой; 30 секунд и 2 минуты."},{"id":"q2","type":"multi_select","question":"В уроке «2-of-3» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать паттерн готовым до закрытия третьей свечи","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"последовательность зелёная–красная–зелёная; третья зелёная закрывается на уровне/выше максимума первой; 30 секунд и 2 минуты","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"ждать полного закрытия третьей свечи и проверки условия максимума","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «2-of-3» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «2-of-3». Для темы «2-of-3» можно пропустить проверку ситуации, если уже выполнено условие: ждать полного закрытия третьей свечи и проверки условия максимума.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «2-of-3» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «2-of-3». Какое действие здесь является главным нарушением логики темы «2-of-3»?","options":[{"value":"A","label":"проверить именно 2-of-3 перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"считать паттерн готовым до закрытия третьей свечи","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: последовательность зелёная–красная–зелёная; третья зелёная закрывается на уровне/выше максимума первой; 30 секунд и 2 минуты."},{"id":"q5","type":"single_select","question":"Какое утверждение точно относится к материалу «2-of-3» в уроке «2-of-3»?","options":[{"value":"A","label":"Этот параметр или условие заменяет исходное правило урока на другое.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"В 2-of-3 третья зелёная свеча должна закрыться на уровне или выше максимума первой зелёной.","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"Результат сделки заранее определяет правильность правила.","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"Любой внешний сигнал автоматически отменяет условия урока.","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Вспомни конкретную настройку или условие, которое отличает этот урок от соседних тем."}],"keyTakeaway":"Последовательность свечей должна быть полной: зелёная → красная → зелёная.","facts":["Последовательность свечей должна быть полной: зелёная → красная → зелёная.","Ключевое условие — закрытие третьей свечи на/выше максимума первой зелёной.","Решение принимается после полного закрытия свечи."],"sourceTitle":"2-of-3","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":19,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='strategies-two-of-three';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"База психологии в источнике посвящена типичным проблемам новичков и пошаговым действиям, которые помогают не повторять их. Главная задача — замечать собственные реакции до того, как они превращаются в плохое решение.","examples":"Шестой эфир: проблемы новичков, пошаговые инструкции и базовая психология трейдинга.","practice":"Составь журнал из 10 решений: что ты хотел сделать, что чувствовал и что сделал фактически. Для трёх эмоциональных решений укажи, какое правило из урока могло остановить действие.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Психология трейдинга — база». Ситуация: После нескольких неудачных сделок трейдер хочет немедленно увеличить размер следующей позиции. Что из перечисленного лучше всего соответствует теме «психология трейдинга — база»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"остановиться и проверить эмоциональную причину решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: нужно замечать собственные реакции до того, как они превращаются в решение."},{"id":"q2","type":"multi_select","question":"В уроке «Психология трейдинга — база» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"остановиться и проверить эмоциональную причину решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"нужно замечать собственные реакции до того, как они превращаются в решение","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «психология трейдинга — база» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Психология трейдинга — база». Для темы «психология трейдинга — база» можно пропустить проверку ситуации, если уже выполнено условие: остановиться и проверить эмоциональную причину решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «психология трейдинга — база» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Психология трейдинга — база». Какое действие здесь является главным нарушением логики темы «психология трейдинга — база»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно психология трейдинга — база перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"увеличить риск, чтобы быстро вернуть потерянное","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: нужно замечать собственные реакции до того, как они превращаются в решение."}],"keyTakeaway":"Проблему нужно сначала назвать, затем определить триггер и действие контроля.","facts":["Проблему нужно сначала назвать, затем определить триггер и действие контроля.","Результат одной сделки не должен полностью менять план.","Психология работает вместе с системой, а не вместо неё."],"sourceTitle":"Психология трейдинга — база","sourceDuration":"59 минут 45 секунд","lessonFormat":"video","sourceOrder":20,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='psychology-sixth-live';;;;;;
update public.learning_lessons set content=$${"videoUrl":"https://youtu.be/a9y1pxJfDRU","article":"Главный принцип психологии нужно переводить из общей фразы в конкретное торговое поведение. Если принцип нельзя проверить по действиям трейдера, он остаётся абстракцией.","examples":"Отдельный урок по психологии трейдинга. Домашнее задание озвучено в самом видео.","practice":"После просмотра сформулируй главный психологический принцип урока своими словами и проверь его на трёх собственных торговых решениях. Для каждого отметь, где эмоция могла изменить исходный план.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Ситуация: Трейдер говорит, что контролирует эмоции, но после убытка постоянно меняет правила входа. Что из перечисленного лучше всего соответствует теме «психология трейдинга — главный принцип»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оценивать психологию по фактическим действиям","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой."},{"id":"q2","type":"multi_select","question":"В уроке «Психология трейдинга | Урок 1: главный принцип» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"оценивать психологию по фактическим действиям","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «психология трейдинга — главный принцип» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Если выполнить условие «оценивать психологию по фактическим действиям», тема «психология трейдинга — главный принцип» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «психология трейдинга — главный принцип» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Психология трейдинга | Урок 1: главный принцип». Какое действие здесь является главным нарушением логики темы «психология трейдинга — главный принцип»?","options":[{"value":"A","label":"проверить именно психология трейдинга — главный принцип перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать заявление о дисциплине доказательством контроля","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: психологический принцип должен проявляться в наблюдаемом поведении, а не оставаться абстрактной фразой."}],"keyTakeaway":"Фиксируй состояние до сделки, а не только результат после неё.","facts":["Фиксируй состояние до сделки, а не только результат после неё.","Разделяй качество решения и финансовый исход.","Домашнее задание должно превращаться в наблюдаемое действие."],"sourceTitle":"Психология трейдинга | Урок 1: главный принцип","sourceDuration":"YouTube","lessonFormat":"video","sourceOrder":21,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='psychology-main-principle';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Инвестинг от А до Я» связывает выбор валютных пар, фильтрацию сигналов и личный подход автора. Практическая цель — научиться не брать каждый доступный сигнал, а выбирать контекст, который соответствует плану.","examples":"Как выбрать валютные пары, какие сигналы пропускать, как автор торгует и выходит в плюс, и какие ошибки делают новички.","practice":"Выбери 5 валютных пар и составь для каждой короткий фильтр: когда рассматриваешь её, какие ситуации пропускаешь и что должно совпасть перед входом. Затем сравни пары и выбери только те, где критерии выполнимы.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Инвестинг от А до Я — мой личный соус». Ситуация: Есть пять сигналов, но только два соответствуют заранее выбранному контексту и плану. Что из перечисленного лучше всего соответствует теме «Инвестинг от А до Я»?","options":[{"value":"A","label":"рассмотреть только подходящие плану сценарии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"взять все пять сигналов, чтобы не упустить возможность","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: выбор валютной пары и фильтрация сигналов должны соответствовать личному плану, а не количеству доступных сигналов."},{"id":"q2","type":"multi_select","question":"В уроке «Инвестинг от А до Я — мой личный соус» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"рассмотреть только подходящие плану сценарии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"выбор валютной пары и фильтрация сигналов должны соответствовать личному плану, а не количеству доступных сигналов","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"взять все пять сигналов, чтобы не упустить возможность","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Инвестинг от А до Я» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Инвестинг от А до Я — мой личный соус». Если выполнить условие «рассмотреть только подходящие плану сценарии», тема «Инвестинг от А до Я» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Инвестинг от А до Я» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Инвестинг от А до Я — мой личный соус». Какое действие здесь является главным нарушением логики темы «Инвестинг от А до Я»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"взять все пять сигналов, чтобы не упустить возможность","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно Инвестинг от А до Я перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: выбор валютной пары и фильтрация сигналов должны соответствовать личному плану, а не количеству доступных сигналов."}],"keyTakeaway":"Выбор инструмента — часть стратегии.","facts":["Выбор инструмента — часть стратегии.","Пропуск слабого сигнала является частью процесса, а не упущенной возможностью.","Личный подход нужно превращать в проверяемые правила."],"sourceTitle":"Инвестинг от А до Я — мой личный соус","sourceDuration":"19 минут 1 секунда","lessonFormat":"video","sourceOrder":22,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='practice-investing-a-to-z';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Время экспирации должно соответствовать характеру движения. Источник отдельно сравнивает импульс и флет и подчёркивает, что 1 минута не является универсальным решением.","examples":"На что смотреть перед входом, как отличается экспирация при импульсе и флете и почему 1 минута не всегда решение.","practice":"Возьми 8 исторических входов с разным характером движения. Для каждого отдельно выбери срок экспирации и объясни его через тип движения, а не через желание быстрее получить результат.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как подбирать время экспирации для сделки?». Ситуация: Сильный импульс и боковой рынок дают разные темпы движения, но трейдер использует одинаковую экспирацию. Что из перечисленного лучше всего соответствует теме «время экспирации»?","options":[{"value":"A","label":"подбирать срок под характер движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением."},{"id":"q2","type":"multi_select","question":"В уроке «Как подбирать время экспирации для сделки?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"подбирать срок под характер движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «время экспирации» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как подбирать время экспирации для сделки?». Если выполнить условие «подбирать срок под характер движения», тема «время экспирации» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «время экспирации» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как подбирать время экспирации для сделки?». Какое действие здесь является главным нарушением логики темы «время экспирации»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"использовать одну и ту же экспирацию независимо от рынка","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно время экспирации перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: экспирация должна соответствовать характеру движения; 1 минута не является универсальным решением."}],"keyTakeaway":"Сначала оцени характер движения, потом выбирай экспирацию.","facts":["Сначала оцени характер движения, потом выбирай экспирацию.","Импульс и флет требуют разного ожидания по времени.","Точный вход не гарантирует результата при неподходящей экспирации."],"sourceTitle":"Как подбирать время экспирации для сделки?","sourceDuration":"7 минут 57 секунд","lessonFormat":"video","sourceOrder":23,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='timing-expiration';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Торговая интуиция в контексте урока — это не угадывание, а накопленное распознавание повторяющихся ситуаций. Важно отделять опытное ощущение от импульсивного желания войти.","examples":"Автор показывает сделки по интуиции и объясняет подход на примере трёх сделок.","practice":"Выбери 5 исторических ситуаций и сначала запиши интуитивное решение, не открывая следующие свечи. Затем отдельно разложи каждое решение на наблюдаемые признаки и проверь, можно ли объяснить интуицию правилами.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Торговля по интуиции». Ситуация: Трейдер говорит «чувствую вход», но не может назвать ни одного наблюдаемого признака. Что из перечисленного лучше всего соответствует теме «торговля по интуиции»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разложить ощущение на конкретные признаки и проверить их","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки."},{"id":"q2","type":"multi_select","question":"В уроке «Торговля по интуиции» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разложить ощущение на конкретные признаки и проверить их","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «торговля по интуиции» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Торговля по интуиции». Для темы «торговля по интуиции» можно пропустить проверку ситуации, если уже выполнено условие: разложить ощущение на конкретные признаки и проверить их.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «торговля по интуиции» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Торговля по интуиции». Какое действие здесь является главным нарушением логики темы «торговля по интуиции»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно торговля по интуиции перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать любое сильное желание войти интуицией","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: интуиция — накопленное распознавание повторяющихся ситуаций, которое можно разложить на наблюдаемые признаки."}],"keyTakeaway":"Интуиция должна опираться на наблюдаемые признаки рынка.","facts":["Интуиция должна опираться на наблюдаемые признаки рынка.","Проверяй интуитивный вход теми же правилами, что и обычный.","Три удачных сделки не доказывают устойчивость подхода."],"sourceTitle":"Торговля по интуиции","sourceDuration":"11 минут 53 секунды","lessonFormat":"video","sourceOrder":24,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='practice-intuition';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Разбор недели нужен не для поиска виноватой стратегии, а для выявления повторяющихся причин потерь. Сделку следует оценивать по процессу: контекст, вход, риск, дисциплина и результат.","examples":"Пятый эфир: причины потери средств, разбор сделок и причины различий в результатах трейдеров.","practice":"Возьми 10 своих сделок за неделю и классифицируй каждую ошибку: анализ, исполнение, риск или психология. Выбери повторяющуюся категорию и составь одно конкретное правило, которое предотвратит её повторение.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Итоги недели — разбор ошибок». Ситуация: Стратегия дала минус, но запись показывает, что вход был сделан вне правил после эмоциональной серии. Что из перечисленного лучше всего соответствует теме «итоги недели и разбор ошибок»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отнести проблему к процессу исполнения, а не автоматически к стратегии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат."},{"id":"q2","type":"multi_select","question":"В уроке «Итоги недели — разбор ошибок» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отнести проблему к процессу исполнения, а не автоматически к стратегии","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «итоги недели и разбор ошибок» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Итоги недели — разбор ошибок». Если выполнить условие «отнести проблему к процессу исполнения, а не автоматически к стратегии», тема «итоги недели и разбор ошибок» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «итоги недели и разбор ошибок» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Итоги недели — разбор ошибок». Какое действие здесь является главным нарушением логики темы «итоги недели и разбор ошибок»?","options":[{"value":"A","label":"проверить именно итоги недели и разбор ошибок перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"объявить стратегию плохой только по одному результату","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: сделку нужно разбирать по процессу: контекст, вход, риск, дисциплина и результат."}],"keyTakeaway":"Одна убыточная сделка не равна плохой системе.","facts":["Одна убыточная сделка не равна плохой системе.","Повторяющаяся ошибка важнее единичного результата.","Сравнивай причины разных результатов, а не только суммы P&L."],"sourceTitle":"Итоги недели — разбор ошибок","sourceDuration":"38 минут 57 секунд","lessonFormat":"video","sourceOrder":25,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='trade-review-week-errors';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — 15.07.2025» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — 15.07.2025. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Пересмотри разбор и сделай самостоятельный replay: останови график до ключевого момента, запиши свой сценарий и только потом сравни с логикой разбора.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Разбор рынка — 15.07.2025». Ситуация: В разборе разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разбор рынка»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: контекст нужно оценивать до входа."},{"id":"q2","type":"multi_select","question":"В уроке «Разбор рынка — 15.07.2025» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"контекст нужно оценивать до входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «разбор рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Разбор рынка — 15.07.2025». Для темы «разбор рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «разбор рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Разбор рынка — 15.07.2025». Какое действие здесь является главным нарушением логики темы «разбор рынка»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно разбор рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: контекст нужно оценивать до входа."}],"keyTakeaway":"Главная тема урока — Разбор рынка — 15.07.2025.","facts":["Главная тема урока — Разбор рынка — 15.07.2025.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — 15.07.2025","sourceDuration":"7 минут 18 секунд","lessonFormat":"video","sourceOrder":26,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-15072025';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — понедельник 25 августа» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — понедельник 25 августа. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Повтори разбор в режиме replay. На каждом ключевом участке сначала запиши направление и основание решения, затем сравни с тем, что показывается в уроке.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Разбор рынка — понедельник 25 августа». Ситуация: В разборе разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разбор рынка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: контекст нужно оценивать до входа."},{"id":"q2","type":"multi_select","question":"В уроке «Разбор рынка — понедельник 25 августа» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"контекст нужно оценивать до входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «разбор рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Разбор рынка — понедельник 25 августа». Для темы «разбор рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «разбор рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Разбор рынка — понедельник 25 августа». Какое действие здесь является главным нарушением логики темы «разбор рынка»?","options":[{"value":"A","label":"проверить именно разбор рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: контекст нужно оценивать до входа."}],"keyTakeaway":"Главная тема урока — Разбор рынка — понедельник 25 августа.","facts":["Главная тема урока — Разбор рынка — понедельник 25 августа.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка — понедельник 25 августа","sourceDuration":"10 минут 23 секунды","lessonFormat":"video","sourceOrder":27,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-25aug';;;;;;
