update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка в реальном времени — 15.09.2025» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка в реальном времени — 15.09.2025. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Останови запись в трёх местах до входа. Для каждого зафиксируй, что ты видишь и что ждёшь. Затем продолжи запись и сравни своё решение с действиями в эфире.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Разбор рынка в реальном времени — 15.09.2025». Ситуация: В разборе разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разбор рынка»?","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: контекст нужно оценивать до входа."},{"id":"q2","type":"multi_select","question":"В уроке «Разбор рынка в реальном времени — 15.09.2025» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"контекст нужно оценивать до входа","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «разбор рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Разбор рынка в реальном времени — 15.09.2025». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «разбор рынка» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «разбор рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Разбор рынка в реальном времени — 15.09.2025». Какое действие здесь является главным нарушением логики темы «разбор рынка»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно разбор рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: контекст нужно оценивать до входа."}],"keyTakeaway":"Главная тема урока — Разбор рынка в реальном времени — 15.09.2025.","facts":["Главная тема урока — Разбор рынка в реальном времени — 15.09.2025.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Разбор рынка в реальном времени — 15.09.2025","sourceDuration":"9 минут 1 секунда","lessonFormat":"video","sourceOrder":30,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-realtime-1509';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Разбор рынка — утро понедельника» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: разбор рынка — утро понедельника. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Сделай утренний план рынка по материалу: контекст, ключевые зоны, возможные сценарии и условия, при которых сегодня лучше не торговать.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Разбор рынка — утро понедельника». Ситуация: В разборе разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разбор рынка»?","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: контекст нужно оценивать до входа."},{"id":"q2","type":"multi_select","question":"В уроке «Разбор рынка — утро понедельника» выбери два утверждения, которые действительно помогают принять решение в описанной с