update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Что происходит перед сильным движением» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: что происходит перед сильным движением. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Найди 5 участков перед сильным движением. До раскрытия результата отметь признаки накопления/подготовки, изменение активности и последующий импульс.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Что происходит перед сильным движением». Ситуация: В разборе накопление перед сильным движением трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «накопление перед сильным движением»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: важно распознавать состояние до движения, а не только смотреть на уже случившийся импульс."},{"id":"q2","type":"multi_select","question":"В уроке «Что происходит перед сильным движением» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"важно распознавать состояние до движения, а не только смотреть на уже случившийся импульс","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «накопление перед сильным движением» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Что происходит перед сильным движением». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «накопление перед сильным движением» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «накопление перед сильным движением» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Что происходит перед сильным движением». Какое действие здесь является главным нарушением логики темы «накопление перед сильным движением»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно накопление перед сильным движением перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: важно распознавать состояние до движения, а не только смотреть на уже случившийся импульс."}],"keyTakeaway":"Главная тема урока — Что происходит перед сильным движением.","facts":["Главная тема урока — Что происходит перед сильным движением.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Что происходит перед сильным движением","sourceDuration":"4 минуты 37 секунд","lessonFormat":"video","sourceOrder":38,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-accumulation';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Как я анализирую рынок?» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: как я анализирую рынок?. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Повтори два разбора самостоятельно: сначала составь свой анализ и только затем сравни с логикой урока. Выпиши минимум три различия между своим мышлением и показанным подходом.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как я анализирую рынок?». Ситуация: В разборе анализ рынка Амиром трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «анализ рынка Амиром»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата."},{"id":"q2","type":"multi_select","question":"В уроке «Как я анализирую рынок?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «анализ рынка Амиром» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я анализирую рынок?». Для темы «анализ рынка Амиром» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «анализ рынка Амиром» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я анализирую рынок?». Какое действие здесь является главным нарушением логики темы «анализ рынка Амиром»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно анализ рынка Амиром перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: ключевая ценность разбора — последовательность наблюдений до решения, а не копирование результата."}],"keyTakeaway":"Главная тема урока — Как я анализирую рынок?.","facts":["Главная тема урока — Как я анализирую рынок?.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Как я анализирую рынок?","sourceDuration":"13 минут 58 секунд","lessonFormat":"video","sourceOrder":39,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-how-amir-analyzes';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Какой таймфрейм выбрать новичку?» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: какой таймфрейм выбрать новичку?. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Возьми один и тот же рынок и проведи наблюдение на нескольких таймфреймах. Запиши, какой масштаб информации даёт каждый и какой из них позволяет тебе принимать решения без лишнего шума.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Какой таймфрейм выбрать новичку?». Ситуация: В разборе таймфрейм для новичка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «таймфрейм для новичка»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план."},{"id":"q2","type":"multi_select","question":"В уроке «Какой таймфрейм выбрать новичку?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «таймфрейм для новичка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Какой таймфрейм выбрать новичку?». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «таймфрейм для новичка» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «таймфрейм для новичка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Какой таймфрейм выбрать новичку?». Какое действие здесь является главным нарушением логики темы «таймфрейм для новичка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно таймфрейм для новичка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: таймфрейм нужно выбирать так, чтобы движение можно было спокойно анализировать и соблюдать план."}],"keyTakeaway":"Главная тема урока — Какой таймфрейм выбрать новичку?.","facts":["Главная тема урока — Какой таймфрейм выбрать новичку?.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Какой таймфрейм выбрать новичку?","sourceDuration":"3 минуты 34 секунды","lessonFormat":"video","sourceOrder":40,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-beginner-tf';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Почему цена разворачивается от уровня?» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: почему цена разворачивается от уровня?. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Найди 5 разворотов возле уровней. Для каждого укажи, что произошло до разворота, какая реакция появилась и в какой момент ты мог бы считать сценарий подтверждённым.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Почему цена разворачивается от уровня?». Ситуация: В разборе разворот от уровня трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «разворот от уровня»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание."},{"id":"q2","type":"multi_select","question":"В уроке «Почему цена разворачивается от уровня?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «разворот от уровня» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Почему цена разворачивается от уровня?». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «разворот от уровня» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «разворот от уровня» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Почему цена разворачивается от уровня?». Какое действие здесь является главным нарушением логики темы «разворот от уровня»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно разворот от уровня перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: разворот имеет смысл рассматривать через реакцию цены в области, а не через одно касание."}],"keyTakeaway":"Главная тема урока — Почему цена разворачивается от уровня?.","facts":["Главная тема урока — Почему цена разворачивается от уровня?.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Почему цена разворачивается от уровня?","sourceDuration":"3 минуты 24 секунды","lessonFormat":"video","sourceOrder":41,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-reversal-level';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Фейк-пробой, импульс и откат» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: фейк-пробой, импульс и откат. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Найди 5 ложных пробоев и для каждого отметь сам пробой, реакцию после него и откат. Сформулируй признак, который помог бы не принять ложный пробой за продолжение движения.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Фейк-пробой, импульс и откат». Ситуация: В разборе фейк-пробой, импульс и откат трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «фейк-пробой, импульс и откат»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: выход за уровень может оказаться фейк-пробоем; важна реакция после выхода."},{"id":"q2","type":"multi_select","question":"В уроке «Фейк-пробой, импульс и откат» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"выход за уровень может оказаться фейк-пробоем; важна реакция после выхода","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «фейк-пробой, импульс и откат» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Фейк-пробой, импульс и откат». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «фейк-пробой, импульс и откат» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «фейк-пробой, импульс и откат» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Фейк-пробой, импульс и откат». Какое действие здесь является главным нарушением логики темы «фейк-пробой, импульс и откат»?","options":[{"value":"A","label":"проверить именно фейк-пробой, импульс и откат перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: выход за уровень может оказаться фейк-пробоем; важна реакция после выхода."}],"keyTakeaway":"Главная тема урока — Фейк-пробой, импульс и откат.","facts":["Главная тема урока — Фейк-пробой, импульс и откат.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Фейк-пробой, импульс и откат","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":42,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-false-breakout';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Как понять, куда движется рынок?» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: как понять, куда движется рынок?. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Выбери 5 графиков и перед открытием следующих свечей определи рабочее направление. Запиши аргументы и условие, при котором ты изменишь первоначальный взгляд.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как понять, куда движется рынок?». Ситуация: В разборе направление рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «направление рынка»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: направление определяется последовательностью и контекстом движения, а не одной свечой."},{"id":"q2","type":"multi_select","question":"В уроке «Как понять, куда движется рынок?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"направление определяется последовательностью и контекстом движения, а не одной свечой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «направление рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как понять, куда движется рынок?». Если выполнить условие «сначала восстановить контекст, реакцию и подтверждение до принятия решения», тема «направление рынка» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «направление рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как понять, куда движется рынок?». Какое действие здесь является главным нарушением логики темы «направление рынка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"проверить именно направление рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: направление определяется последовательностью и контекстом движения, а не одной свечой."}],"keyTakeaway":"Главная тема урока — Как понять, куда движется рынок?.","facts":["Главная тема урока — Как понять, куда движется рынок?.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Как понять, куда движется рынок?","sourceDuration":"Пост","lessonFormat":"post","sourceOrder":43,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-direction';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: пилотный выпуск | разбор рынка от амира. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Останови пилотный разбор перед тремя решениями и самостоятельно ответь: что сейчас происходит, почему возможен вход и что отменяет идею. Затем сравни с разбором.","quiz":[{"id":"q1","type":"single_select","question":"Урок «ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА». Ситуация: В разборе пилотный разбор рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «пилотный разбор рынка»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: цель разбора — самостоятельно сформировать сценарий до результата и затем сравнить логику."},{"id":"q2","type":"multi_select","question":"В уроке «ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"цель разбора — самостоятельно сформировать сценарий до результата и затем сравнить логику","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «пилотный разбор рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА». Для темы «пилотный разбор рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «пилотный разбор рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА». Какое действие здесь является главным нарушением логики темы «пилотный разбор рынка»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно пилотный разбор рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: цель разбора — самостоятельно сформировать сценарий до результата и затем сравнить логику."}],"keyTakeaway":"Главная тема урока — ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА.","facts":["Главная тема урока — ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"ПИЛОТНЫЙ ВЫПУСК | РАЗБОР РЫНКА ОТ АМИРА","sourceDuration":"17 минут 5 секунд","lessonFormat":"video","sourceOrder":44,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-amir-pilot';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Фазы рынка» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: фазы рынка. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Найди по одному примеру каждой наблюдаемой фазы рынка. Для каждого опиши признаки фазы и какое поведение трейдера будет разумным в ней.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Фазы рынка». Ситуация: В разборе фазы рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «фазы рынка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: разные фазы требуют разного прочтения движения и не должны смешиваться в один сценарий."},{"id":"q2","type":"multi_select","question":"В уроке «Фазы рынка» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"разные фазы требуют разного прочтения движения и не должны смешиваться в один сценарий","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «фазы рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Фазы рынка». Для темы «фазы рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «фазы рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Фазы рынка». Какое действие здесь является главным нарушением логики темы «фазы рынка»?","options":[{"value":"A","label":"проверить именно фазы рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: разные фазы требуют разного прочтения движения и не должны смешиваться в один сценарий."}],"keyTakeaway":"Главная тема урока — Фазы рынка.","facts":["Главная тема урока — Фазы рынка.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Фазы рынка","sourceDuration":"10 минут 20 секунд","lessonFormat":"video","sourceOrder":45,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-phases';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Как я анализирую рынок — полный разбор» — практический материал по чтению рынка. Основная задача такого разбора — не запомнить конкретное движение цены, а научиться видеть контекст до входа: где находится цена, что происходило перед движением, какая реакция появилась и почему сценарий имеет смысл.\n\nРазбирай рынок последовательно: контекст → ключевая зона/состояние → реакция цены → сценарий → подтверждение → только затем решение. Не переноси результат одной исторической сделки как гарантию будущей.","examples":"Практический разбор: как я анализирую рынок — полный разбор. Материал показывает логику чтения рынка и наблюдения за поведением цены.","practice":"Повтори полный разбор как самостоятельное упражнение: сначала анализ, затем сравнение с уроком. Отдельно отметь, какие наблюдения оказались ключевыми.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как я анализирую рынок — полный разбор». Ситуация: В разборе полный разбор анализа рынка трейдер видит движение, но хочет сразу использовать его результат как готовый сигнал. Что из перечисленного лучше всего соответствует теме «полный разбор анализа рынка»?","options":[{"value":"A","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: ценность полного разбора — последовательная проверка контекста до решения."},{"id":"q2","type":"multi_select","question":"В уроке «Как я анализирую рынок — полный разбор» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ценность полного разбора — последовательная проверка контекста до решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала восстановить контекст, реакцию и подтверждение до принятия решения","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «полный разбор анализа рынка» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я анализирую рынок — полный разбор». Для темы «полный разбор анализа рынка» можно пропустить проверку ситуации, если уже выполнено условие: сначала восстановить контекст, реакцию и подтверждение до принятия решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «полный разбор анализа рынка» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я анализирую рынок — полный разбор». Какое действие здесь является главным нарушением логики темы «полный разбор анализа рынка»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать итог исторической сделки как гарантию будущего результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно полный разбор анализа рынка перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: ценность полного разбора — последовательная проверка контекста до решения."}],"keyTakeaway":"Главная тема урока — Как я анализирую рынок — полный разбор.","facts":["Главная тема урока — Как я анализирую рынок — полный разбор.","Смотри на последовательность событий до входа, а не только на итог сделки.","Практический разбор ценен тем, что превращает решение трейдера в последовательность наблюдений."],"sourceTitle":"Как я анализирую рынок — полный разбор","sourceDuration":"13 минут 58 секунд","lessonFormat":"video","sourceOrder":46,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='market-analysis-duplicate';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Материал «Важность долгосрочной прибыли» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Аудио о важности долгосрочного результата и системного взгляда на прибыль.","practice":"Составь план из 20 сделок и заранее определи, что для тебя означает приемлемый результат серии, а не одной сделки. После серии сравни ожидания с фактическим поведением.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Важность долгосрочной прибыли». Ситуация: После двух плюсов трейдер хочет нарушить лимит риска ради более крупной прибыли. Что из перечисленного лучше всего соответствует теме «долгосрочная прибыль»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сохранить правило риска и оценивать результат на серии сделок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важнее качество серии решений, чем попытка получить максимум от одной сделки."},{"id":"q2","type":"multi_select","question":"В уроке «Важность долгосрочной прибыли» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"важнее качество серии решений, чем попытка получить максимум от одной сделки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранить правило риска и оценивать результат на серии сделок","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «долгосрочная прибыль» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Важность долгосрочной прибыли». Для темы «долгосрочная прибыль» можно пропустить проверку ситуации, если уже выполнено условие: сохранить правило риска и оценивать результат на серии сделок.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «долгосрочная прибыль» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Важность долгосрочной прибыли». Какое действие здесь является главным нарушением логики темы «долгосрочная прибыль»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"увеличить риск из-за недавних плюсов","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"проверить именно долгосрочная прибыль перед решением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важнее качество серии решений, чем попытка получить максимум от одной сделки."}],"keyTakeaway":"Главная тема — Важность долгосрочной прибыли.","facts":["Главная тема — Важность долгосрочной прибыли.","Правило полезно только тогда, когда его можно проверить по действиям.","Оценивай не только результат, но и качество выполнения процесса."],"sourceTitle":"Важность долгосрочной прибыли","sourceDuration":"8 минут 59 секунд","lessonFormat":"audio","sourceOrder":47,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='money-long-term-profit';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Концепция работы в Amir Family Exclusive» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал о концепции работы в Amir Family Exclusive и механике авторской модели.","practice":"Сформулируй своими словами, чем системный подход отличается от набора случайных сигналов. Затем проверь это на пяти исторических сделках и укажи, какие элементы системы реально использовались.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Концепция работы в Amir Family Exclusive». Ситуация: Ученик пытается превратить название программы в конкретный торговый сигнал. Что из перечисленного лучше всего соответствует теме «Amir Family Exclusive»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изучать концепцию через наблюдаемые правила и условия","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа."},{"id":"q2","type":"multi_select","question":"В уроке «Концепция работы в Amir Family Exclusive» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изучать концепцию через наблюдаемые правила и условия","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["B","D"],"hint":"Сверяй варианты с конкретной темой «Amir Family Exclusive» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Концепция работы в Amir Family Exclusive». Для темы «Amir Family Exclusive» можно пропустить проверку ситуации, если уже выполнено условие: изучать концепцию через наблюдаемые правила и условия.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «Amir Family Exclusive» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Концепция работы в Amir Family Exclusive». Какое действие здесь является главным нарушением логики темы «Amir Family Exclusive»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно Amir Family Exclusive перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать сам факт участия готовым торговым сигналом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: урок следует воспринимать как отдельную концепцию работы и последовательность принятия решений, а не как универсальную кнопку входа."}],"keyTakeaway":"Основная тема материала — Концепция работы в Amir Family Exclusive.","facts":["Основная тема материала — Концепция работы в Amir Family Exclusive.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Концепция работы в Amir Family Exclusive","sourceDuration":"9 минут 30 секунд","lessonFormat":"video","sourceOrder":48,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-amir-family';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Материал «Как понять, когда не стоит торговать?» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Гайд о ситуациях, когда лучше не торговать, с акцентом на сохранение денег и долгосрочный результат.","practice":"Найди 10 ситуаций, где вход кажется привлекательным, но есть причина не торговать. Для каждой назови конкретный стоп-фактор и проверь, как изменилось бы решение при его отсутствии.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как понять, когда не стоит торговать?». Ситуация: На рынке нет понятного сценария, но трейдер хочет войти ради активности. Что из перечисленного лучше всего соответствует теме «когда не стоит торговать»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"пропустить ситуацию без достаточных условий","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: отказ от сделки — часть системы управления качеством решений."},{"id":"q2","type":"multi_select","question":"В уроке «Как понять, когда не стоит торговать?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"отказ от сделки — часть системы управления качеством решений","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"пропустить ситуацию без достаточных условий","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «когда не стоит торговать» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как понять, когда не стоит торговать?». Если выполнить условие «пропустить ситуацию без достаточных условий», тема «когда не стоит торговать» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «когда не стоит торговать» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как понять, когда не стоит торговать?». Какое действие здесь является главным нарушением логики темы «когда не стоит торговать»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно когда не стоит торговать перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"открыть сделку, чтобы не оставаться без позиции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: отказ от сделки — часть системы управления качеством решений."}],"keyTakeaway":"Главная тема — Как понять, когда не стоит торговать?.","facts":["Главная тема — Как понять, когда не стоит торговать?.","Правило полезно только тогда, когда его можно проверить по действиям.","Оценивай не только результат, но и качество выполнения процесса."],"sourceTitle":"Как понять, когда не стоит торговать?","sourceDuration":"11 минут 31 секунда","lessonFormat":"video","sourceOrder":49,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='money-when-not-trade';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Материал «Как я постоянно выхожу в плюс?» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Аудиоматериал об авторском подходе к стабильному положительному результату.","practice":"Веди журнал 20 решений и оцени не только результат, но и соблюдение заранее заданных правил. В конце посчитай, сколько минусов возникло из-за рынка, а сколько — из-за нарушения собственного плана.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как я постоянно выхожу в плюс?». Ситуация: После одного убытка трейдер меняет стратегию, чтобы следующая сделка обязательно была плюсовой. Что из перечисленного лучше всего соответствует теме «постоянный плюс»?","options":[{"value":"A","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранять проверяемый процесс и оценивать серию","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: системность важнее попытки гарантировать плюс каждой отдельной сделкой."},{"id":"q2","type":"multi_select","question":"В уроке «Как я постоянно выхожу в плюс?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сохранять проверяемый процесс и оценивать серию","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"системность важнее попытки гарантировать плюс каждой отдельной сделкой","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «постоянный плюс» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как я постоянно выхожу в плюс?». Для темы «постоянный плюс» можно пропустить проверку ситуации, если уже выполнено условие: сохранять проверяемый процесс и оценивать серию.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «постоянный плюс» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как я постоянно выхожу в плюс?». Какое действие здесь является главным нарушением логики темы «постоянный плюс»?","options":[{"value":"A","label":"проверить именно постоянный плюс перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"менять правила после каждого отдельного результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: системность важнее попытки гарантировать плюс каждой отдельной сделкой."}],"keyTakeaway":"Главная тема — Как я постоянно выхожу в плюс?.","facts":["Главная тема — Как я постоянно выхожу в плюс?.","Правило полезно только тогда, когда его можно проверить по действиям.","Оценивай не только результат, но и качество выполнения процесса."],"sourceTitle":"Как я постоянно выхожу в плюс?","sourceDuration":"4 минуты 39 секунд","lessonFormat":"audio","sourceOrder":50,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='money-constantly-profit';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Материал «Трейдинг начинается в голове — урок 1» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Почему сливается депозит: серии минусов, завышенный риск, отыгрыш, эмоциональная и системная торговля.","practice":"Составь карту трёх своих рискованных сценариев: триггер → мысль → действие → последствия. Для каждого придумай заранее правило остановки.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Трейдинг начинается в голове — урок 1». Ситуация: Трейдер видит хороший сигнал, но находится в состоянии после серии эмоциональных решений. Что из перечисленного лучше всего соответствует теме «трейдинг начинается в голове»?","options":[{"value":"A","label":"сначала оценить состояние и готовность соблюдать правила","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: решение начинается с состояния и правил трейдера до открытия позиции."},{"id":"q2","type":"multi_select","question":"В уроке «Трейдинг начинается в голове — урок 1» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сначала оценить состояние и готовность соблюдать правила","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"решение начинается с состояния и правил трейдера до открытия позиции","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «трейдинг начинается в голове» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Трейдинг начинается в голове — урок 1». Если выполнить условие «сначала оценить состояние и готовность соблюдать правила», тема «трейдинг начинается в голове» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «трейдинг начинается в голове» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Трейдинг начинается в голове — урок 1». Какое действие здесь является главным нарушением логики темы «трейдинг начинается в голове»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно трейдинг начинается в голове перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"игнорировать состояние, если график выглядит привлекательным","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: решение начинается с состояния и правил трейдера до открытия позиции."}],"keyTakeaway":"Главная тема — Трейдинг начинается в голове — урок 1.","facts":["Главная тема — Трейдинг начинается в голове — урок 1.","Правило полезно только тогда, когда его можно проверить по действиям.","Оценивай не только результат, но и качество выполнения процесса."],"sourceTitle":"Трейдинг начинается в голове — урок 1","sourceDuration":"18 минут 29 секунд","lessonFormat":"video","sourceOrder":51,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='psychology-trading-starts-head';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Материал «Как зарабатывать много с минимальными рисками?» рассматривай как правило управления качеством решений. Смысл урока — превратить тему в наблюдаемое поведение: что делать до сделки, что нельзя делать во время серии и какое действие помогает сохранить системность.\n\nХорошее правило должно быть коротким, проверяемым и применимым до того, как эмоция уже повлияла на решение.","examples":"Соотношение риска и прибыли, построение торговой стратегии и плана; затронуты переживания за баланс, догоны и потеря контроля.","practice":"Составь личный план риска на серию из 20 сделок. Заранее укажи допустимый риск, максимальное число попыток и действие после серии минусов. Не меняй параметры после начала серии.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как зарабатывать много с минимальными рисками?». Ситуация: Чтобы быстрее заработать, трейдер предлагает резко увеличить размер позиции при том же качестве сигнала. Что из перечисленного лучше всего соответствует теме «много с минимальными рисками»?","options":[{"value":"A","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сохранять контролируемый риск и искать качество решений","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки."},{"id":"q2","type":"multi_select","question":"В уроке «Как зарабатывать много с минимальными рисками?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сохранять контролируемый риск и искать качество решений","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["C","D"],"hint":"Сверяй варианты с конкретной темой «много с минимальными рисками» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как зарабатывать много с минимальными рисками?». Для темы «много с минимальными рисками» можно пропустить проверку ситуации, если уже выполнено условие: сохранять контролируемый риск и искать качество решений.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «много с минимальными рисками» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как зарабатывать много с минимальными рисками?». Какое действие здесь является главным нарушением логики темы «много с минимальными рисками»?","options":[{"value":"A","label":"проверить именно много с минимальными рисками перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"увеличить ставку ради ускорения результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Ищи действие, которое прямо противоречит условию: рост результата должен сочетаться с контролем риска, а не строиться на увеличении ставки."}],"keyTakeaway":"Главная тема — Как зарабатывать много с минимальными рисками?.","facts":["Главная тема — Как зарабатывать много с минимальными рисками?.","Правило полезно только тогда, когда его можно проверить по действиям.","Оценивай не только результат, но и качество выполнения процесса."],"sourceTitle":"Как зарабатывать много с минимальными рисками?","sourceDuration":"20 минут 33 секунды","lessonFormat":"video","sourceOrder":52,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='money-minimal-risks';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Как торгует Амир?» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Авторская рубрика: стиль торговли, технический анализ, точки принятия решения, риск-менеджмент и мышление.","practice":"Разбери одну историческую сделку по четырём блокам: технический анализ, торговый план, риск-менеджмент, мышление. Для каждого блока запиши наблюдаемый факт, а не общий вывод.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как торгует Амир?». Ситуация: Ученик видит успешную сделку Амирa и хочет повторить только направление сделки. Что из перечисленного лучше всего соответствует теме «как торгует Амир»?","options":[{"value":"A","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разобрать причины и последовательность решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B"],"hint":"Опирайся на условие урока: важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение."},{"id":"q2","type":"multi_select","question":"В уроке «Как торгует Амир?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"разобрать причины и последовательность решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «как торгует Амир» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как торгует Амир?». Для темы «как торгует Амир» можно пропустить проверку ситуации, если уже выполнено условие: разобрать причины и последовательность решения.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «как торгует Амир» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как торгует Амир?». Какое действие здесь является главным нарушением логики темы «как торгует Амир»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно как торгует Амир перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"копировать только направление уже совершённой сделки","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: важно разбирать процесс: что замечено, почему выбран сценарий и какое условие подтверждает решение."}],"keyTakeaway":"Основная тема материала — Как торгует Амир?.","facts":["Основная тема материала — Как торгует Амир?.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Как торгует Амир?","sourceDuration":"12 минут 6 секунд","lessonFormat":"video","sourceOrder":53,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-how-amir-trades';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Как торгует Амир? — Часть 2» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Три сделки, логика рынка и напоминание об одной стратегии в конце видео.","practice":"Повтори упражнение из урока на одной своей исторической ситуации: сначала сформулируй логику рынка, затем сделай решение и после этого сравни его с альтернативным сценарием.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Как торгует Амир? — Часть 2». Ситуация: Ученик запомнил результат сделки, но не может объяснить условия её открытия. Что из перечисленного лучше всего соответствует теме «как торгует Амир — часть 2»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"вернуться к условиям и логике решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов."},{"id":"q2","type":"multi_select","question":"В уроке «Как торгует Амир? — Часть 2» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"вернуться к условиям и логике решения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «как торгует Амир — часть 2» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Как торгует Амир? — Часть 2». Если выполнить условие «вернуться к условиям и логике решения», тема «как торгует Амир — часть 2» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «как торгует Амир — часть 2» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Как торгует Амир? — Часть 2». Какое действие здесь является главным нарушением логики темы «как торгует Амир — часть 2»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"проверить именно как торгует Амир — часть 2 перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"считать результат достаточным объяснением","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: продолжение полезно изучать как процесс принятия решений, а не как список готовых сигналов."}],"keyTakeaway":"Основная тема материала — Как торгует Амир? — Часть 2.","facts":["Основная тема материала — Как торгует Амир? — Часть 2.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Как торгует Амир? — Часть 2","sourceDuration":"8 минут 50 секунд","lessonFormat":"video","sourceOrder":54,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-how-amir-trades-2';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Книга «Зональный трейдинг»» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Книга о зонах, эмоциях, психологии и практических советах.","practice":"После изучения материала выбери 5 идей из книги и для каждой сделай практический пример на графике. Отдельно отметь, где идея требует контекста и не должна использоваться как самостоятельный сигнал.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Книга «Зональный трейдинг»». Ситуация: Цена немного вышла за границу зоны, но реакция сохраняется внутри области. Что из перечисленного лучше всего соответствует теме «книга «Зональный трейдинг»»?","options":[{"value":"A","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценивать зону как область с контекстом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Опирайся на условие урока: зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку."},{"id":"q2","type":"multi_select","question":"В уроке «Книга «Зональный трейдинг»» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"оценивать зону как область с контекстом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["A","D"],"hint":"Сверяй варианты с конкретной темой «книга «Зональный трейдинг»» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Книга «Зональный трейдинг»». Для темы «книга «Зональный трейдинг»» можно пропустить проверку ситуации, если уже выполнено условие: оценивать зону как область с контекстом.","options":[{"value":"true","label":"Верно","feedback":"Утверждение ошибочно: выполнение одного действия не отменяет остальные условия темы."},{"value":"false","label":"Неверно","feedback":"Неверность утверждения подтверждается тем, что тема применяется вместе с контекстом и условиями ситуации."}],"correctValues":["false"],"hint":"Проверь, превращает ли указанное действие тему «книга «Зональный трейдинг»» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Книга «Зональный трейдинг»». Какое действие здесь является главным нарушением логики темы «книга «Зональный трейдинг»»?","options":[{"value":"A","label":"проверить именно книга «Зональный трейдинг» перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"отменять всю идею из-за одного прокола","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: зональный подход требует рассматривать область цены и её реакцию, а не одну математическую отметку."}],"keyTakeaway":"Основная тема материала — Книга «Зональный трейдинг».","facts":["Основная тема материала — Книга «Зональный трейдинг».","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Книга «Зональный трейдинг»","sourceDuration":"240 страниц","lessonFormat":"book","sourceOrder":55,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-zone-trading-book';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Forex: кто двигает цену?» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Материал о том, кто двигает цену, почему рынок активен в определённые периоды и какую роль играют банки.","practice":"Нарисуй схему участников движения цены по материалу и привяжи её к одному реальному участку графика. Объясни, какие наблюдения на графике соответствуют твоей схеме.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Forex: кто двигает цену?». Ситуация: Цена движется, и трейдер пытается объяснить движение только показанием одного осциллятора. Что из перечисленного лучше всего соответствует теме «Forex: кто двигает цену»?","options":[{"value":"A","label":"рассматривать движение через рыночный контекст и взаимодействие сторон","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору."},{"id":"q2","type":"multi_select","question":"В уроке «Forex: кто двигает цену?» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"рассматривать движение через рыночный контекст и взаимодействие сторон","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["B","C"],"hint":"Сверяй варианты с конкретной темой «Forex: кто двигает цену» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Forex: кто двигает цену?». Если выполнить условие «рассматривать движение через рыночный контекст и взаимодействие сторон», тема «Forex: кто двигает цену» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Forex: кто двигает цену» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Forex: кто двигает цену?». Какое действие здесь является главным нарушением логики темы «Forex: кто двигает цену»?","options":[{"value":"A","label":"считать один индикатор единственной причиной движения","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"проверить именно Forex: кто двигает цену перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Ищи действие, которое прямо противоречит условию: анализ должен учитывать участников и силы рынка, а не сводиться к одному индикатору."}],"keyTakeaway":"Основная тема материала — Forex: кто двигает цену?.","facts":["Основная тема материала — Forex: кто двигает цену?.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Forex: кто двигает цену?","sourceDuration":"13 минут 55 секунд","lessonFormat":"video","sourceOrder":56,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-forex-market';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Урок «Новое обучение аналитика — личная стратегия» формирует базовое понимание темы. Изучай его не как набор фраз, а как последовательность принятия решения: что наблюдаем → что это означает → какое условие должно появиться → когда решение лучше пропустить.\n\nТезисы ниже сформулированы как учебное объяснение по названию и описанию исходного материала; конкретные детали видео следует сверять с самой записью.","examples":"Новый обучающий материал аналитика о личной торговой стратегии.","practice":"Составь черновик собственной стратегии: рынок, условия, вход, пропуск, риск и способ проверки. Затем проведи 10 исторических тестов и запиши, какие правила оказались неоднозначными.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Новое обучение аналитика — личная стратегия». Ситуация: Две одинаково выглядящие сделки получают разные решения без изменения условий. Что из перечисленного лучше всего соответствует теме «личная стратегия аналитика»?","options":[{"value":"A","label":"уточнить критерии стратегии и сделать их проверяемыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A"],"hint":"Опирайся на условие урока: личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять."},{"id":"q2","type":"multi_select","question":"В уроке «Новое обучение аналитика — личная стратегия» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"уточнить критерии стратегии и сделать их проверяемыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «личная стратегия аналитика» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Новое обучение аналитика — личная стратегия». Если выполнить условие «уточнить критерии стратегии и сделать их проверяемыми», тема «личная стратегия аналитика» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «личная стратегия аналитика» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Новое обучение аналитика — личная стратегия». Какое действие здесь является главным нарушением логики темы «личная стратегия аналитика»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно личная стратегия аналитика перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"оставить критерии намеренно размытыми","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Ищи действие, которое прямо противоречит условию: личная стратегия должна быть формализована так, чтобы её условия можно было повторять и проверять."}],"keyTakeaway":"Основная тема материала — Новое обучение аналитика — личная стратегия.","facts":["Основная тема материала — Новое обучение аналитика — личная стратегия.","Главное правило должно быть сформулировано своими словами.","Практика нужна для проверки понимания на графике, а не для механического повторения результата."],"sourceTitle":"Новое обучение аналитика — личная стратегия","sourceDuration":"10 минут 38 секунд","lessonFormat":"video","sourceOrder":57,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='advanced-personal-strategy-training';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Запись «Первая эксклюзивная сессия» используй как тренировку наблюдения. Не пытайся просто повторить сделки из записи. Отслеживай, что трейдер видел до решения: структуру, движение цены, уровень, реакцию и причины входа/пропуска.\n\nТвоя цель — поставить запись на паузу перед ключевым моментом и самостоятельно сформулировать сценарий, а затем сравнить его с решением автора.","examples":"Запись торговой сессии: Первая эксклюзивная сессия. Используй запись как практический материал для наблюдения за решениями и контекстом.","practice":"Выбери три момента сессии и до просмотра продолжения сформулируй собственный сценарий. После просмотра отметь, что совпало и что отличалось.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Первая эксклюзивная сессия». Ситуация: Во время «Первая эксклюзивная сессия» запись ещё не дошла до решения, но ученик хочет сразу посмотреть результат. Что из перечисленного лучше всего соответствует теме «Первая эксклюзивная сессия»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок."},{"id":"q2","type":"multi_select","question":"В уроке «Первая эксклюзивная сессия» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","C"],"hint":"Сверяй варианты с конкретной темой «Первая эксклюзивная сессия» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Первая эксклюзивная сессия». Если выполнить условие «поставить запись на паузу и сформулировать собственный сценарий до результата», тема «Первая эксклюзивная сессия» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Первая эксклюзивная сессия» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Первая эксклюзивная сессия». Какое действие здесь является главным нарушением логики темы «Первая эксклюзивная сессия»?","options":[{"value":"A","label":"узнать результат сделки заранее","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"проверить именно Первая эксклюзивная сессия перед решением","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант соответствует условиям задачи."}],"correctValues":["D"],"hint":"Ищи действие, которое прямо противоречит условию: запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок."}],"keyTakeaway":"Запись сессии — материал для тренировки процесса принятия решений.","facts":["Запись сессии — материал для тренировки процесса принятия решений.","Главное — причина действия до результата, а не сам факт плюса или минуса.","Пауза перед входом превращает просмотр в активную практику."],"sourceTitle":"Первая эксклюзивная сессия","sourceDuration":"27 минут 7 секунд","lessonFormat":"session","sourceOrder":58,"curriculumVersion":"V32 ACADEMY"}$$::jsonb,status='published',updated_at=now() where slug='session-first-exclusive';;;;;;
update public.learning_lessons set content=$${"videoUrl":"","article":"Запись «Вторая эксклюзивная сессия» используй как тренировку наблюдения. Не пытайся просто повторить сделки из записи. Отслеживай, что трейдер видел до решения: структуру, движение цены, уровень, реакцию и причины входа/пропуска.\n\nТвоя цель — поставить запись на паузу перед ключевым моментом и самостоятельно сформулировать сценарий, а затем сравнить его с решением автора.","examples":"Запись торговой сессии: Вторая эксклюзивная сессия. Используй запись как практический материал для наблюдения за решениями и контекстом.","practice":"Сделай replay трёх решений из сессии. Для каждого запиши контекст, ожидание и условие отмены, а затем сравни с фактическим развитием.","quiz":[{"id":"q1","type":"single_select","question":"Урок «Вторая эксклюзивная сессия». Ситуация: Во время «Вторая эксклюзивная сессия» запись ещё не дошла до решения, но ученик хочет сразу посмотреть результат. Что из перечисленного лучше всего соответствует теме «Вторая эксклюзивная сессия»?","options":[{"value":"A","label":"изменить условия анализа после появления результата","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"ориентироваться только на прошлую прибыль","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"C","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"D","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["C"],"hint":"Опирайся на условие урока: запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок."},{"id":"q2","type":"multi_select","question":"В уроке «Вторая эксклюзивная сессия» выбери два утверждения, которые действительно помогают принять решение в описанной ситуации.","options":[{"value":"A","label":"запись нужно использовать для самостоятельного анализа до момента решения, а не для механического копирования сделок","feedback":"Этот вариант соответствует условиям задачи."},{"value":"B","label":"поставить запись на паузу и сформулировать собственный сценарий до результата","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"D","label":"сделать вывод только по прошлой прибыли","feedback":"Этот вариант не соответствует условиям задачи."}],"correctValues":["A","B"],"hint":"Сверяй варианты с конкретной темой «Вторая эксклюзивная сессия» и описанной ситуацией, а не с общим впечатлением от рынка."},{"id":"q3","type":"true_false","question":"Урок «Вторая эксклюзивная сессия». Если выполнить условие «поставить запись на паузу и сформулировать собственный сценарий до результата», тема «Вторая эксклюзивная сессия» всё равно требует учитывать контекст, указанный в уроке.","options":[{"value":"true","label":"Верно","feedback":"Утверждение сохраняет необходимость контекста и не превращает отдельное действие в автоматический сигнал."},{"value":"false","label":"Неверно","feedback":"Утверждение не отменяет контекст: оно прямо следует из способа применения темы в уроке."}],"correctValues":["true"],"hint":"Проверь, превращает ли указанное действие тему «Вторая эксклюзивная сессия» в автоматическое правило или нет."},{"id":"q4","type":"single_select","question":"Урок «Вторая эксклюзивная сессия». Какое действие здесь является главным нарушением логики темы «Вторая эксклюзивная сессия»?","options":[{"value":"A","label":"заменить исходный сценарий другим без изменения наблюдаемой ситуации","feedback":"Этот вариант не соответствует условиям задачи."},{"value":"B","label":"сначала узнать исход сделки и затем считать его готовым сигналом","feedback":"Этот вариант соответствует условиям задачи."},{"value":"C","labe