-- V34: persistent quiz attempts / achievement source.
create table if not exists public.learning_quiz_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  lesson_id uuid not null references public.learning_lessons(id) on delete cascade,
  score numeric(5,2) not null default 0,
  passed boolean not null default false,
  answers jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists learning_quiz_attempts_user_idx on public.learning_quiz_attempts(user_id, created_at desc);
create index if not exists learning_quiz_attempts_lesson_idx on public.learning_quiz_attempts(user_id, lesson_id, created_at desc);
alter table public.learning_quiz_attempts enable row level security;
drop policy if exists learning_quiz_attempts_select on public.learning_quiz_attempts;
create policy learning_quiz_attempts_select on public.learning_quiz_attempts for select to authenticated using (auth.uid()=user_id or public.is_admin());
drop policy if exists learning_quiz_attempts_insert on public.learning_quiz_attempts;
create policy learning_quiz_attempts_insert on public.learning_quiz_attempts for insert to authenticated with check (auth.uid()=user_id);
drop policy if exists learning_quiz_attempts_update on public.learning_quiz_attempts;
create policy learning_quiz_attempts_update on public.learning_quiz_attempts for update to authenticated using (auth.uid()=user_id or public.is_admin()) with check (auth.uid()=user_id or public.is_admin());
notify pgrst, 'reload schema';
